        options() {
            return {
                onEachFeature: this.onEachFeatureFunction
            };
        },
        styleFunction() {
            const fillColor = this.fillColor; // important! need touch fillColor in computed for re-calculate when change fillColor
            return () => {
                return {
                    weight: 2,
                    color: "#ECEFF1",
                    opacity: 1,
                    fillColor: fillColor,
                    fillOpacity: 1
                };
            };
        },
        onEachFeatureFunction() {
            if (!this.enableTooltip) {
                return () => { };
            }
            return (feature, layer) => {
                layer.bindTooltip(
                    "<div>code:" +
                    feature.properties.code +
                    "</div><div>nom: " +
                    feature.properties.nom +
                    "</div>",
                    { permanent: false, sticky: true }
                );
            };
        },
        rows() {
            return this.tableData.length
        },
        layer() {
            return this.layers[this.layerIndex]
        }
    },
    mounted() {
        this.setFullHeight();
        window.addEventListener('resize', this.setFullHeight);
        document.body.removeAttribute("data-mapsidebar-showuser");
    },
    methods: {
        setFullHeight() {
            var wHeight = window.innerHeight - 180;
            var mapHeight = wHeight;
            this.$refs.fullHeightDiv.style.height = wHeight + 'px';
        },
        /**
         * Toggle Map rightbar
         */
        toggleMapRightSidebar() {
            document.body.classList.toggle("map-right-bar-enabled");
            console.log(document.body.classList);
        },
        hideMapRightSidebar() {
            document.body.classList.remove("map-right-bar-enabled");
        },
    },
    beforeDestroy() {
        window.removeEventListener('resize', this.setFullHeight);
    },
    middleware: 'router-auth'
}
