<template>
    <div>
        <PageHeader :title="title" :items="items" />
        <div class="row">
            <div class="col-12">
                <div class="spatial-container" ref="fullHeightDiv">
                    <div class="card">
                        <div class="card-body">
                            <div id="map-wrapper">
                                <l-map ref="map" :crs="layer.crs" :zoom="zoom" :center="center"
                                    style="height: 100%; min-height: 650px;">
                                    <l-tile-layer :url="layer.url" :subdomains="layer.subdomains"
                                        :attribution="layer.attribution" />
                                    <l-control-layers position="bottomleft"></l-control-layers>
                                    <l-tile-layer v-for="tileProvider in tileProviders" :key="tileProvider.name"
                                        :name="tileProvider.name" :visible="tileProvider.visible" :url="tileProvider.url"
                                        :attribution="tileProvider.attribution" layer-type="base" />
                                    <l-geo-json :geojson="this.geojson"></l-geo-json>
                                </l-map>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <div class="map-paramater-button nav-link right-bar-toggle toggle-right">
            <a href="javascript:void(0);" @click="toggleMapRightSidebar">
                <i class="fe-settings noti-icon toggle-right"></i>
            </a>
        </div>
        <MapRightbar />
    </div>
</template>
